css:
/* Анимация успешной отправки формы заявки. Цвета — токены дизайн-системы (--color-*), в скобках запасные.
   Состояния — атрибут data-state на .lead: idle → sending → sent | error. Анимируются только opacity, transform, clip-path. */
.lead {
  position: relative; display: grid; max-width: 480px; padding: 24px; box-sizing: border-box;
  border: 1px solid var(--color-border, #e5e7eb); border-radius: 20px;
  background: var(--color-surface, #ffffff); color: var(--color-text, #111827);
}
.lead > .lead__form, .lead > .lead__done { grid-area: 1 / 1; } /* одна ячейка: высота блока постоянна */
.lead__form {
  display: grid; gap: 12px;
  transition: opacity 180ms cubic-bezier(.3, 0, 1, 1), transform 180ms cubic-bezier(.3, 0, 1, 1); /* уход быстрее прихода */
}
.lead__h { margin: 0 0 4px; font-size: 26px; line-height: 1.2; }
.lead__field { display: grid; gap: 6px; font-size: 14px; color: var(--color-text-muted, #4b5563); }
.lead__field input {
  min-height: 48px; padding: 12px 14px; box-sizing: border-box; font: inherit; font-size: 16px; /* 16px — iPhone не зумит поле */
  color: var(--color-text, #111827); background: var(--color-background, #ffffff);
  border: 1px solid var(--color-border, #d1d5db); border-radius: 12px;
}
.lead__field input:focus-visible { outline: 3px solid var(--color-primary, #1d4ed8); outline-offset: 1px; }
.lead__consent { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; line-height: 1.4; color: var(--color-text-muted, #4b5563); }
.lead__consent input { width: 24px; height: 24px; margin: 0; flex: none; accent-color: var(--color-primary, #1d4ed8); }
.lead__consent a { color: var(--color-link, #1d4ed8); }
.lead__btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  min-height: 52px; padding: 14px 24px; border: 0; border-radius: 999px; cursor: pointer;
  background: var(--color-primary, #1d4ed8); color: var(--color-on-primary, #ffffff); font: inherit; font-weight: 600;
}
.lead__btn:focus-visible { outline: 3px solid var(--color-text, #111827); outline-offset: 3px; }
.lead__label, .lead__dots { transition: opacity 150ms cubic-bezier(.2, 0, 0, 1); }
/* Точки лежат поверх надписи: ширина кнопки не меняется */
.lead__dots { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; gap: 6px; opacity: 0; }
.lead__dots i { width: 8px; height: 8px; border-radius: 50%; background: currentColor; opacity: .35; }
.lead__dots i:nth-child(2) { --d: 150ms; }
.lead__dots i:nth-child(3) { --d: 300ms; }
.lead__error { min-height: 3em; margin: 0; font-size: 14px; line-height: 1.5; color: var(--color-error, #b91c1c); } /* место под две строки заранее */
.lead__live { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Отправка: надпись гаснет, точки мигают волной. Повторов 14 (≈ 12,9 с) — чуть дольше таймаута запроса 12 с:
   точки не замирают раньше, чем придёт ответ или текст ошибки, и не мигают бесконечно (WCAG 2.2.2) */
.lead[data-state="sending"] .lead__label { opacity: 0; }
.lead[data-state="sending"] .lead__dots { opacity: 1; }
.lead[data-state="sending"] .lead__btn { cursor: progress; }
.lead[data-state="sending"] .lead__dots i { animation: lead-dot 900ms ease-in-out var(--d, 0ms) 14 both; }

/* Ошибка: текст опускается на 4px и проявляется, поля остаются заполненными */
.lead[data-state="error"] .lead__error { animation: lead-drop 200ms cubic-bezier(.2, 0, 0, 1) both; }

/* Успех: форма уходит, на её месте — значок с галочкой, заголовок и текст */
.lead[data-state="sent"] .lead__form { opacity: 0; transform: scale(.98); pointer-events: none; }
.lead__done {
  display: grid; justify-items: center; align-content: center; gap: 12px; text-align: center;
  opacity: 0; pointer-events: none;
}
.lead[data-state="sent"] .lead__done { opacity: 1; pointer-events: auto; transition: opacity 200ms cubic-bezier(.2, 0, 0, 1) 100ms; }
.lead__badge {
  position: relative; display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%;
  background: var(--color-success, #15803d); color: var(--color-background, #ffffff); /* галочка цветом фона: читается и в тёмной теме */
}
.lead__badge::after { /* круговая волна, один раз */
  content: ""; position: absolute; inset: 0; border-radius: 50%;
  border: 2px solid var(--color-success, #15803d); opacity: 0; pointer-events: none;
}
.lead__check { width: 32px; height: 32px; }
.lead__title { margin: 0; font-size: 24px; line-height: 1.2; }
.lead__title:focus { outline: none; } /* фокус ставит скрипт, чтобы диктор прочёл заголовок; это не кнопка */
.lead__text { margin: 0; max-width: 34ch; color: var(--color-text-muted, #4b5563); line-height: 1.5; }
.lead__next { color: var(--color-link, #1d4ed8); font-weight: 600; }
.lead__title { --d: 300ms; }
.lead__text { --d: 360ms; }
.lead__next { --d: 420ms; }
.lead[data-state="sent"] .lead__badge { animation: lead-pop 280ms cubic-bezier(.175, .885, .32, 1.275) 100ms both; } /* перелёт ~5% */
.lead[data-state="sent"] .lead__badge::after { animation: lead-ring 520ms cubic-bezier(.2, 0, 0, 1) 260ms both; }
.lead[data-state="sent"] .lead__check { animation: lead-draw 220ms cubic-bezier(.2, 0, 0, 1) 260ms both; } /* галочка «рисуется» слева направо */
.lead[data-state="sent"] .lead__title,
.lead[data-state="sent"] .lead__text,
.lead[data-state="sent"] .lead__next { animation: lead-rise 240ms cubic-bezier(.2, 0, 0, 1) var(--d, 0ms) both; }

@keyframes lead-dot { 0%, 80%, 100% { opacity: .35; transform: scale(.75); } 40% { opacity: 1; transform: scale(1); } }
@keyframes lead-blink { 0%, 80%, 100% { opacity: .35; } 40% { opacity: 1; } }
@keyframes lead-drop { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@keyframes lead-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes lead-pop { from { opacity: 0; transform: scale(.6); } to { opacity: 1; transform: scale(1); } }
@keyframes lead-ring { from { opacity: .6; transform: scale(1); } to { opacity: 0; transform: scale(1.6); } }
@keyframes lead-draw { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes lead-rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

@media (prefers-reduced-motion: reduce) {
  /* Убираем: масштаб формы и значка, волну, прорисовку галочки, подъём текста, пульсацию размера точек */
  .lead[data-state="sent"] .lead__form { transform: none; }
  .lead[data-state="sent"] .lead__badge,
  .lead[data-state="sent"] .lead__badge::after,
  .lead[data-state="sent"] .lead__check,
  .lead[data-state="sent"] .lead__title,
  .lead[data-state="sent"] .lead__text,
  .lead[data-state="sent"] .lead__next { animation: none; }
  /* Смягчаем: смена формы на «спасибо» — короткое затухание 150ms; ошибка и точки — только прозрачность */
  .lead__form, .lead__label, .lead__dots { transition-duration: 150ms; }
  .lead[data-state="sent"] .lead__done { transition-duration: 150ms; }
  .lead[data-state="sending"] .lead__dots i { animation-name: lead-blink; }
  .lead[data-state="error"] .lead__error { animation: lead-fade 150ms linear both; }
  /* Оставляем: фокус на заголовке, текст для диктора, цвета состояний */
}

js:
// Подключать с defer. Анимация «спасибо» — только после ответа сервера {"ok": true}, не раньше.
document.querySelectorAll('[data-lead]').forEach(lead => {
  const form = lead.querySelector('.lead__form'), done = lead.querySelector('.lead__done');
  const err = lead.querySelector('.lead__error'), live = lead.querySelector('.lead__live');
  const FAIL = 'Не получилось отправить. Нажмите ещё раз — всё, что вы ввели, осталось в полях.';
  form.addEventListener('submit', async e => {
    e.preventDefault();
    if (lead.dataset.state === 'sending') return; // двойной клик не шлёт вторую заявку
    lead.dataset.state = 'sending';
    err.textContent = ''; // очищаем, чтобы повтор той же ошибки диктор прочёл снова
    live.textContent = 'Отправляем заявку';
    let msg = '';
    try {
      const r = await fetch(form.action, {
        method: 'POST',
        body: new FormData(form), // вместе с полями уйдёт и скрытый CSRF-токен, если он есть в форме
        headers: { Accept: 'application/json' }, // без него сервер может ответить HTML-страницей
        signal: AbortSignal.timeout ? AbortSignal.timeout(12000) : undefined, // старый браузер — без таймаута, но заявка уходит
      });
      const data = await r.json().catch(() => ({})); // HTML вместо JSON = успех не подтверждён
      if (r.ok && (data.ok === true || data.success === true)) {
        done.inert = false;
        lead.dataset.state = 'sent';
        form.inert = true; // форму не достать ни Tab, ни диктором
        live.textContent = '';
        done.querySelector('.lead__title')?.focus({ preventScroll: true }); // диктор прочтёт «Заявка принята»
        return;
      }
      if (r.status === 422 && typeof data.message === 'string') msg = data.message; // что поправить в полях
    } catch { /* сеть, таймаут, блокировщик — покажем общий текст */ }
    lead.dataset.state = 'error';
    live.textContent = '';
    err.textContent = msg || FAIL; // отказ всегда виден на том же экране
  });
});

gsap_alt:
// npm i gsap; import gsap from 'gsap' — без CDN. Нужен, только если GSAP уже есть на лендинге: сам приём целиком делается на CSS.
// В CSS удалить правила .lead[data-state="sent"] для .lead__badge, .lead__check, .lead__title, .lead__text, .lead__next
// (волну .lead__badge::after оставить: GSAP не анимирует псевдоэлементы), а в правилах .lead[data-state="sent"] .lead__form
// и .lead[data-state="sent"] .lead__done оставить только pointer-events. В JS сразу после lead.dataset.state = 'sent' вызвать playSent(lead).
function playSent(lead) {
  const q = s => lead.querySelector(s);
  const form = q('.lead__form'), done = q('.lead__done');
  // CSS-переходы из рецепта спорили бы с GSAP за opacity: форма висела бы поверх «спасибо» ещё ~0,2 с,
  // а в reduced motion transition-duration из медиазапроса включает переход по умолчанию all. Инлайн сильнее любого правила.
  form.style.transition = done.style.transition = 'none';
  // Настройку читаем в момент успеха: gsap.matchMedia при её смене откатил бы таймлайн и вернул форму на экран.
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) {
    return gsap.timeline()
      .to(form, { opacity: 0, duration: 0.15 })
      .fromTo(done, { opacity: 0 }, { opacity: 1, duration: 0.15 }, '<0.1');
  }
  return gsap.timeline({ defaults: { ease: 'power2.out' } })
    .to(form, { opacity: 0, scale: 0.98, duration: 0.18, ease: 'power2.in' })
    .fromTo(done, { opacity: 0 }, { opacity: 1, duration: 0.2 }, '<0.1')
    .fromTo(q('.lead__badge'), { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.28, ease: 'back.out(1.4)' }, '<')
    .fromTo(q('.lead__check'), { clipPath: 'inset(0% 100% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.22 }, '<0.16')
    .fromTo(['.lead__title', '.lead__text', '.lead__next'].map(q), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.24, stagger: 0.06 }, '<0.04');
}
